#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;using System.Windows.Threading;
namespace FileCompass {
 internal static class DialogCardsTests {
  static void Pump(Window window){NavigationTests.Wait(Task.Delay(100));window.UpdateLayout();}
  internal static int Run(string root){Directory.CreateDirectory(root);CodeEditorWindow editor=null;var log=new List<string>();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);log.Add(label);};try{
   SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();L.ChangeLanguage("cs-CZ");AppearanceTheme.Apply("Light");AppearanceTheme.SetMotif("Clean");string lf=Path.Combine(root,"document-with-a-readable-name.html");File.WriteAllText(lf,"first\nsecond\n",new UTF8Encoding(false));
   editor=new CodeEditorWindow(null){Width=1180,Height=800,Left=-18000,Top=-18000,ShowActivated=false,ShowInTaskbar=false,WindowStartupLocation=WindowStartupLocation.Manual};editor.Show();NavigationTests.Wait(editor.OpenFile(lf));Pump(editor);
   var heading=AdvancedToolsTests.Visual<TextBlock>(editor).Single(x=>x.Text==L.Text("codeEditor.title"));var filename=AdvancedToolsTests.Visual<TextBlock>(editor).Single(x=>x.IsVisible&&x.Text==Path.GetFileName(lf));check(filename.TranslatePoint(new Point(),editor).X>heading.TranslatePoint(new Point(),editor).X&&Math.Abs(filename.TranslatePoint(new Point(),editor).Y+filename.ActualHeight/2-heading.TranslatePoint(new Point(),editor).Y-heading.ActualHeight/2)<2,"filename shares the editor title row, aligned at the right");check(editor.Tabs.Template.FindName("Headers",editor.Tabs)==null,"one document has no redundant tab header");NextStageTests.Draw(editor,Path.Combine(root,"editor-header.png"));byte[] bytes=File.ReadAllBytes(lf);NavigationTests.Wait(editor.Save(false));check(File.ReadAllBytes(lf).SequenceEqual(bytes)&&editor.Current.EolChoice==0,"existing LF documents retain their original byte format");
   var doc=editor.NewDocument(new EditorSaveLocation{Folder=root});check(doc.EolChoice==1,"new documents default to Windows CRLF");doc.Editor.Text="one\ntwo\n";string target=Path.Combine(root,"new-windows.txt");editor.ChooseLocalPath=d=>target;NavigationTests.Wait(editor.Save(false));check(File.ReadAllBytes(target).SequenceEqual(Encoding.UTF8.GetBytes("one\r\ntwo\r\n")),"saving a new document normalizes line endings to CRLF without a BOM");Pump(editor);check(editor.Tabs.Template.FindName("Headers",editor.Tabs) is FrameworkElement,"multiple documents retain their tab strip");
   foreach(var answer in new[]{MessageBoxResult.Yes,MessageBoxResult.No,MessageBoxResult.Cancel}){
    Exception failure=null;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(60)};timer.Tick+=delegate{var popup=editor.OwnedWindows.Cast<Window>().FirstOrDefault(x=>x.IsVisible&&x.Title==L.Text("codeEditor.unsavedTitle"));if(popup==null)return;timer.Stop();try{popup.UpdateLayout();var buttons=FluentUiTests.Children<Button>(popup).ToArray();check(new[]{"codeEditor.save","codeEditor.discardChanges","codeEditor.keepEditing"}.All(k=>buttons.Any(x=>Convert.ToString(x.Content)==L.Text(k))),"save prompt uses explicit action labels: "+answer);check(!AdvancedToolsTests.Visual<TextBox>(popup).Any(),"description is readable message text rather than a bordered input field: "+answer);check(buttons.Single(x=>x.IsDefault).Content.Equals(L.Text("codeEditor.keepEditing")),"save prompt retains the safe continue-editing default: "+answer);check(AdvancedToolsTests.Visual<Border>(popup).Count(x=>Convert.ToString(x.Tag).StartsWith("dialog-"))==3,"dialog has rounded header, content and footer cards: "+answer);NextStageTests.Draw(popup,Path.Combine(root,"save-changes-"+answer+".png"));if(answer==MessageBoxResult.Cancel)popup.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(popup),0,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent});else buttons.Single(x=>Convert.ToString(x.Content)==L.Text(answer==MessageBoxResult.Yes?"codeEditor.save":"codeEditor.discardChanges")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception ex){failure=ex;popup.Close();}};timer.Start();var result=MessageBox.SaveChanges(editor,Path.GetFileName(lf));timer.Stop();if(failure!=null)throw failure;check(result==answer,"save/discard/Escape preserves the exact requested result: "+answer);
   }
   Exception genericFailure=null;var genericTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(60)};genericTimer.Tick+=delegate{var popup=editor.OwnedWindows.Cast<Window>().FirstOrDefault(x=>x.IsVisible&&x.Title=="Information");if(popup==null)return;genericTimer.Stop();try{popup.UpdateLayout();check(!AdvancedToolsTests.Visual<TextBox>(popup).Any(),"general explanatory dialogs also use readable text instead of input styling");NextStageTests.Draw(popup,Path.Combine(root,"information-card.png"));FluentUiTests.Children<Button>(popup).Single(x=>x.IsCancel).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception ex){genericFailure=ex;popup.Close();}};genericTimer.Start();var generic=MessageBox.Show(editor,"Tato operace změní vybrané položky.\n\nZkontrolujte nastavení a potvrďte pokračování.","Information",MessageBoxButton.OKCancel,MessageBoxImage.Information,MessageBoxResult.Cancel);genericTimer.Stop();if(genericFailure!=null)throw genericFailure;check(generic==MessageBoxResult.Cancel,"general dialog keeps its explicit cancellation result");
   foreach(var document in editor.Documents){document.FormatModified=false;document.Editor.IsModified=false;}editor.Close();editor=null;File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(editor!=null){foreach(var document in editor.Documents){document.FormatModified=false;document.Editor.IsModified=false;}editor.Close();}}}
 }
}
#endif
